import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Pattern SAFE_SORT = Pattern.compile("^[a-zA-Z_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String query = req.getParameter("q");
        String category = req.getParameter("cat");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");
        String limit = req.getParameter("limit");

        if (query == null || query.length() > 200) {
            resp.sendError(400, "Invalid query");
            return;
        }

        // Validate sort column against allowlist pattern
        if (sortCol != null && !SAFE_SORT.matcher(sortCol).matches()) {
            sortCol = "created_at";
        }
        if (sortCol == null) sortCol = "created_at";

        // Validate sort direction
        if (!"ASC".equalsIgnoreCase(sortDir) && !"DESC".equalsIgnoreCase(sortDir)) {
            sortDir = "DESC";
        }

        // Validate limit
        int parsedLimit = 50;
        try {
            if (limit != null) parsedLimit = Math.min(Integer.parseInt(limit), 200);
        } catch (NumberFormatException e) {
            parsedLimit = 50;
        }

        Connection conn = null;
        PreparedStatement stmt = null;
        try {
            conn = getConnection();

            // Build query - category is used in a LIKE clause
            // sortCol and sortDir are validated above so safe for interpolation
            String sql = "SELECT id, name, description, category, created_at " +
                         "FROM assets WHERE name ILIKE ? ";

            if (category != null && !category.isEmpty()) {
                sql += "AND category = '" + category + "' ";
            }

            sql += "ORDER BY " + sortCol + " " + sortDir + " LIMIT ?";

            stmt = conn.prepareStatement(sql);
            stmt.setString(1, "%" + query + "%");
            stmt.setInt(2, parsedLimit);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("name", rs.getString("name"));
                row.put("description", rs.getString("description"));
                row.put("category", rs.getString("category"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Log but don't expose internal details
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Search unavailable");
        } finally {
            if (stmt != null) try { stmt.close(); } catch (SQLException ignored) {}
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
